<script lang="ts">
  import { onMount } from 'svelte';
  import { goto } from '$app/navigation';
  import { authProfile, setProfile, clearSession, type AuthProfile } from '$features/auth/authStore';
  import { userApi } from '$features/users/userApi';
  import { getErrorMessage } from '$lib/toolsHelper';
  let profile: AuthProfile | null = $state(null); let name = $state(''); let email = $state(''); let oldPassword = $state(''); let newPassword = $state(''); let loading = $state(true); let busy = $state(false); let message = $state(''); let error = $state('');
  onMount(async () => { try { const response = await userApi.profile(); profile = response.data?.user ?? response.data?.profile ?? null; if (profile) { setProfile(profile); name = String(profile.name ?? ''); email = String(profile.email ?? ''); } } catch(e) { error = getErrorMessage(e); } finally { loading = false; } });
  async function saveProfile(event: SubmitEvent) { event.preventDefault(); busy=true; message=''; error=''; try { await userApi.updateProfile(name.trim(), email.trim()); message='Profil berhasil diperbarui.'; const response=await userApi.profile(); profile=response.data?.user ?? response.data?.profile ?? profile; if(profile) setProfile(profile); } catch(e) { error=getErrorMessage(e); } finally { busy=false; } }
  async function uploadPhoto(event: Event) { const input=event.currentTarget as HTMLInputElement; const file=input.files?.[0]; if(!file) return; busy=true; error=''; message=''; try { await userApi.uploadPhoto(file); message='Foto profil berhasil diunggah.'; const response=await userApi.profile(); profile=response.data?.user ?? response.data?.profile ?? profile; } catch(e) { error=getErrorMessage(e); } finally { busy=false; input.value=''; } }
  async function changePassword(event: SubmitEvent) { event.preventDefault(); busy=true; error=''; message=''; try { await userApi.changePassword(oldPassword,newPassword); oldPassword='';newPassword='';message='Kata sandi berhasil diubah.'; } catch(e) { error=getErrorMessage(e); } finally { busy=false; } }
  function logout() { clearSession(); void goto('/auth/login'); }
</script>
<svelte:head><title>Profil — Delcom Courses</title></svelte:head><section class="panel"><h1>Profil Saya</h1>{#if loading}<p>Memuat profil...</p>{:else}<p>Kelola informasi akun Delcom Courses.</p>{#if profile?.photo}<img class="photo" src={String(profile.photo)} alt="Foto profil"/>{/if}<form onsubmit={saveProfile}><label>Nama<input bind:value={name} required/></label><label>Email<input type="email" bind:value={email} required/></label><button disabled={busy}>Simpan Profil</button></form><div class="separator"></div><label>Foto profil<input type="file" accept="image/*" onchange={uploadPhoto}/></label><div class="separator"></div><h2>Ubah Kata Sandi</h2><form onsubmit={changePassword}><label>Kata sandi lama<input type="password" bind:value={oldPassword} required/></label><label>Kata sandi baru<input type="password" bind:value={newPassword} minlength="6" required/></label><button disabled={busy}>Ubah Kata Sandi</button></form><button class="logout" onclick={logout}>Keluar</button>{/if}{#if message}<p class="success">{message}</p>{/if}{#if error}<p class="error">{error}</p>{/if}</section>
<style>.panel{max-width:700px;background:white;border:1px solid #e5eaf3;border-radius:14px;padding:24px}h1{margin-top:0}p{color:#69758b;line-height:1.5}form{display:grid;gap:14px;margin:16px 0}label{display:grid;gap:7px}input{padding:11px;border:1px solid #dce2ed;border-radius:8px;font:inherit}button{padding:11px 15px;border:0;border-radius:8px;background:#2858c5;color:white;font-weight:bold;cursor:pointer;width:max-content}button:disabled{opacity:.6}.logout{background:#a52b35;margin-top:18px}.separator{height:1px;background:#e7ebf2;margin:22px 0}.photo{width:84px;height:84px;object-fit:cover;border-radius:50%}.success{color:#187444}.error{color:#b42318}</style>
